            //
            aOrbiterA = (aOrbiterA + aOrbiterB) + 0x42F50CD71AF753B1ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterA) ^ 0xAB07B1B0AB6748CBULL) ^ aOrbiterUpdateSaltF[((aIndex + 27U)) & S_SALT1];
