            //
            aIngress = (RotL64(aWaterLaneA[((aIndex + 9690U)) & S_BLOCK1], 19U) ^ RotL64(aWindLaneC[((aIndex + 9792U)) & S_BLOCK1], 37U));
            aIngress ^= (RotL64(pSnow[((aIndex + 13551U)) & S_BLOCK1], 56U) ^ RotL64(aFireLaneB[((aIndex + 9641U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseA(((aIngress ^ aDomainWordIngress) ^ aNonceWordH));
