            aCross = (RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 31212U)) & S_BLOCK1], 10U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 30249U)) & S_BLOCK1], 27U));
