            aOrbiterI = (aWandererK + RotL64(aIngress, 3U)) + 0x267E0A5D49C7AAFBULL;
            aOrbiterC = ((aWandererC + RotL64(aCross, 53U)) + 0x763745C1FD82A141ULL) + aNonceWordL;
            aOrbiterE = (((aWandererD + RotL64(aPrevious, 19U)) + RotL64(aCarry, 35U)) + 0xA8F631FD3D5A45E5ULL) + aNonceWordO;
            aOrbiterH = (((aWandererJ + RotL64(aScatter, 26U)) + RotL64(aCarry, 13U)) + 0x3AD26F1194CA6982ULL) + aPhaseBOrbiterAssignSaltB[((aIndex + 6U)) & S_SALT1];
            aOrbiterA = (aWandererH + RotL64(aCross, 51U)) + 0x3D15C28536236EDCULL;
            aOrbiterK = (aWandererB + RotL64(aPrevious, 39U)) + 0x29A1D28366CE3BF9ULL;
            aOrbiterD = ((aWandererA + RotL64(aIngress, 11U)) + RotL64(aCarry, 43U)) + 0xF18B0AD87921858CULL;
            aOrbiterJ = (aWandererG + RotL64(aScatter, 41U)) + 0x7D1CC5D4C15F7BF8ULL;
            aOrbiterB = (aWandererI + RotL64(aCross, 29U)) + 0x796B0AC7613705B7ULL;
            aOrbiterG = ((aWandererF + RotL64(aScatter, 47U)) + 0xAA9DD57DA0F4D0B8ULL) + aPhaseBOrbiterAssignSaltF[(((31U - aIndex) + 20U)) & S_SALT1];
