            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0xC2C40B9737466D75ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterE) ^ 0xCF868725845E70C6ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x702F4D1A6E21E711ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0x5C726CC96F48BA86ULL;
            aOrbiterH = (((aOrbiterH ^ aOrbiterB) ^ 0x60B01EA4920C74D1ULL) ^ aPhaseBOrbiterUpdateSaltE[(((31U - aIndex) + 5U)) & S_SALT1]) ^ aNonceWordD;
            aOrbiterH = RotL64((aOrbiterH * 0x85BF25B041F8F1D3ULL), 53U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0x89555ABB021E1B5CULL) + aPhaseBOrbiterUpdateSaltD[((aIndex + 3U)) & S_SALT1];
