            //
            aWandererG = aWandererG ^ ((RotL64(aScatter, 11U) + RotL64(aOrbiterD, 13U)) + aOrbiterH);
            aWandererB = aWandererB + (((RotL64(aCross, 50U) + RotL64(aOrbiterI, 23U)) + aOrbiterF) + RotL64(aCarry, 47U));
            aWandererK = aWandererK ^ (((RotL64(aIngress, 41U) + RotL64(aOrbiterC, 43U)) + aOrbiterH) + aPhaseBWandererUpdateSaltA[(((31U - aIndex) + 20U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aPrevious, 27U) + RotL64(aOrbiterG, 4U)) + aOrbiterI) + RotL64(aCarry, 21U));
            aWandererH = aWandererH ^ ((RotL64(aIngress, 35U) + RotL64(aOrbiterC, 37U)) + aOrbiterF);
