            aOrbiterF = ((aWandererF + RotL64(aScatter, 37U)) + RotL64(aCarry, 35U)) + 0x612E7EEB4AD545E0ULL;
            aOrbiterA = ((aWandererB + RotL64(aCross, 5U)) + RotL64(aCarry, 5U)) + 0x52C3DB81D2FA55E4ULL;
            aOrbiterK = ((aWandererE + RotL64(aScatter, 19U)) + 0xAF5F2F5C7CAF9F2EULL) + aPhaseBOrbiterAssignSaltD[((aIndex + 11U)) & S_SALT1];
            aOrbiterI = (aWandererI + RotL64(aIngress, 29U)) + 0x613E30469C61C168ULL;
