            aCross = (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 8029U)) & S_BLOCK1], 13U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 8625U)) & S_BLOCK1], 21U));
            aCross ^= RotL64(aKeyRowReadA[((aIndex + 8842U)) & W_KEY1], 42U);
            aCross = TwistMix64::DiffuseC(aCross);
            //
            aScatter = (RotL64(aPrevious, 38U) ^ RotL64(aCross, 57U)) + (RotL64(aIngress, 21U) + RotL64(aCarry, 5U));
