            aOrbiterA = ((aWandererB + RotL64(aCross, 4U)) + 0x7828C1D8ED5EECB7ULL) + aPhaseDOrbiterAssignSaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterF = ((aWandererF + RotL64(aScatter, 37U)) + RotL64(aCarry, 35U)) + 0x7221FC5C4189679EULL;
            aOrbiterG = (((aWandererJ + RotL64(aCross, 13U)) + RotL64(aCarry, 3U)) + 0x423E8E6DA7BD05C8ULL) + aPhaseDOrbiterAssignSaltD[(((31U - aIndex) + 26U)) & S_SALT1];
            aOrbiterB = (aWandererH + RotL64(aPrevious, 43U)) + 0x83B85774F479AC63ULL;
            //
            aOrbiterE = ((aOrbiterE + aOrbiterD) + 0x5932EEDB59E37741ULL) + aPhaseDOrbiterUpdateSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterE) ^ 0x8F8AAA673791EDCEULL) ^ aPhaseDOrbiterUpdateSaltA[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x1B4DD554FC92DE71ULL), 29U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x841B0237217AA718ULL;
