            aOrbiterI = ((aOrbiterI + aOrbiterF) + 0x3E08D0EEE0B49DA6ULL) + aPhaseDOrbiterUpdateSaltB[((aIndex + 12U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x39AF960D14CAD3D7ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8395C55A1F83EDADULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x169DEDA1D267261DULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x78577E775960D911ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xCF3179580DB01DDFULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x6540A550C82D98AFULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterA) ^ 0x59C655A275C896B9ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xDBC8AE2595AF08BDULL), 35U);
